#!/usr/bin/env python3
"""Bind window membership to a captured Forward and account for missing runtime slot telemetry."""
import json,sys,hashlib
from pathlib import Path
root=Path(sys.argv[1]);forward=sys.argv[2];mode=sys.argv[3];manifest=json.loads((root/mode/f'forward.{forward}.manifest').read_text());n=len(manifest['input_ids']); start=max(0,n-512)
res={'forward_id':forward,'rid':manifest['rid'],'model_identity':manifest['model_identity'],'token_ids_sha256':hashlib.sha256(json.dumps(manifest['input_ids'],separators=(',',':')).encode()).hexdigest(),'n':n,'positions':[manifest['positions'][0],manifest['positions'][-1]],'hf_sliding_window':512,'sglang_attention_sliding_window':511,'expected_swa_prompt_offsets_inclusive':[start,n-1],'expected_swa_text_positions_inclusive':[start+1,n], 'expected_window_count':min(n,512),'actual_req_to_token_slots_captured':False,'actual_full_to_swa_lut_captured':False,'actual_kernel_kv_indices_captured':False,'basis':'SGLang update_sliding_window_buffer: lens=min(seq_len,511), start=seq_len-lens; HF Gemma4 causal SWA mask includes current token and last 511 preceding token positions; SGLang attention semantics are inclusive window 511 offset. Thus for one-token last-row attention at N=513, expected prior-cache text positions are 2..512 (511 tokens), with current query position 513 handled in extend tile; cache indices correspond to prompt offsets 1..511. This is source-derived, not runtime slot proof.'}
(root/f'window-reconstruction-{mode}-n{n}.json').write_text(json.dumps(res,indent=2)+'\n');print(json.dumps(res,indent=2))
